CREATE OR REPLACE PROCEDURE recalc_market_impact_cost()
LANGUAGE plpgsql
AS $$
DECLARE
    v_mkteffect REAL;
BEGIN
    SELECT mkteffect INTO v_mkteffect FROM systemmonitoring ORDER BY systemmonitoringpivot DESC LIMIT 1;
    INSERT INTO market_impact_cost_log (ordersmark, mic)
    SELECT o.recordvault::TEXT, (o.dealcount * o.dealquote * v_mkteffect * 0.01)::numeric
    FROM orders o WHERE o.orderflow = 'New';
END;
$$;

